import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import Database from "better-sqlite3";
import { drizzle, type BetterSQLite3Database } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import * as schema from "./schema.ts";

const API_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");

/** SQL migrations generated by drizzle-kit (`pnpm --filter @space-mission/api db:generate`). */
export const MIGRATIONS_FOLDER = join(API_ROOT, "drizzle");

/**
 * Default database file: apps/api/.local/game.sqlite.
 * The folder is ignored by apps/api/.gitignore (and *.sqlite by the root .gitignore).
 * Override with the DB_PATH environment variable; ":memory:" gives a throwaway database.
 */
export const DEFAULT_DB_PATH = join(API_ROOT, ".local", "game.sqlite");

export type Db = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

/** Opens the database and brings its schema up to date. */
export function openDb(path: string = process.env.DB_PATH ?? DEFAULT_DB_PATH): Db {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
  const sqlite = new Database(path);
  sqlite.pragma("foreign_keys = ON");
  const db = drizzle(sqlite, { schema });
  migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  return db;
}
